mapper.select:
SELECT r.* FROM room r
WHERE r.status = 0

    AND r.location LIKE CONCAT('%', #{location}, '%')


    AND r.capacity >= #{minCapacity}


    AND (

        r.equipment LIKE CONCAT('%', #{item}, '%')

    )

AND r.id NOT IN (
    SELECT DISTINCT room_id FROM booking
    WHERE date = #{date}
    AND status != 3
    AND (
        (start_time < #{endTime} AND end_time > #{startTime})
    )
)

mapper.update:
UPDATE room
SET name = #{name}, location = #{location}, capacity = #{capacity},
    equipment = #{equipment}, status = #{status}
WHERE id = #{id}
